def parse_text_document(document: str) -> dict:
    try:
        import re
        from collections import defaultdict
        cache = {}
        sentences = re.split("[.!?]", document)
        result = defaultdict(list)
        for sentence in sentences:
            if sentence:
                words = re.findall("\b\w+\b", sentence)
                for word in words:
                    if word.lower() not in cache:
                        cache[word.lower()] = len(result)
                        result[word.lower()].append(sentence)
        return dict(result)
    except Exception as e:
        print("An error occurred: " + str(e))
        return {}

def compute_fibonacci(n, memo = {}):
    if n in memo:
        return memo[n]
    if n <= 2:
        return 1
    fib = compute_fibonacci(n-1, memo) + compute_fibonacci(n-2, memo)
    memo[n] = fib
    return fib

