def calculate_monte_carlo_pi(num_samples: int) -> float:
    if num_samples <= 0:
        raise ValueError("Number of samples must be a positive integer")
    inside_circle = 0
    total_samples = 0
    for _ in range(num_samples):
        x = random.uniform(0, 1)
        y = random.uniform(0, 1)
        distance = x**2 + y**2
        if distance <= 1:
            inside_circle += 1
        total_samples += 1
    return 4 * inside_circle / total_samples

def optimize_network_latency(graph, source_node, target_node):
    # Create a cache to store intermediate results
    latency_cache = {}

    def calculate_latency(node, target):
        if node == target:
            return 0
        if (node, target) in latency_cache:
            return latency_cache[(node, target)]

        min_latency = float("inf")
        for neighbor in graph[node]:
            latency = calculate_latency(neighbor, target) + 1
            if latency < min_latency:
                min_latency = latency

        latency_cache[(node, target)] = min_latency
        return min_latency

    return calculate_latency(source_node, target_node)

