def process_student_records(student_list):
    if not isinstance(student_list, list):
        raise ValueError("Input must be a list of student records")
    try:
        valid_records = [record for record in student_list if isinstance(record, dict) and 'name' in record and 'grades' in record]
        average_grades = {record['name']: sum(record['grades']) / len(record['grades']) for record in valid_records}
        return average_grades
    except ZeroDivisionError:
        raise ValueError("Student has no grades")
    except Exception as e:
        raise ValueError("Error processing student records: " + str(e))

def handle_api_errors(error_list, logger):
    # Sort errors by severity
    error_list.sort(key=lambda x: x['severity'])

    # Create a list of error messages
    error_messages = [
        "Error {0}: {1}".format(error['code'], error['message']) 
        for error in error_list if error['severity'] == 'CRITICAL'
    ]

    # Create a list of warning messages
    warning_messages = [
        "Warning {0}: {1}".format(error['code'], error['message']) 
        for error in error_list if error['severity'] == 'WARNING'
    ]

    # Log error and warning messages
    for error_message in error_messages:
        logger.error(error_message)
    for warning_message in warning_messages:
        logger.warning(warning_message)

    # Return a dictionary with error and warning counts
    return {
        'error_count': len(error_messages),
        'warning_count': len(warning_messages)
    }

